"use strict";(function(){const t=new IntersectionObserver(r=>{r.forEach(e=>{if(!e.target.isConnected)return t.unobserve(e.target);e.isIntersecting&&(e.target.innerHTML=e.target.getAttribute("data-value"),t.unobserve(e.target))})},{threshold:.5,rootMargin:"70% 0% -30%"});Behaviours.add("odometer",r=>{typeof Odometer=="function"&&r.querySelectorAll(".odometer").forEach(e=>{const n=e.innerHTML;e.setAttribute("data-value",n),new Odometer({el:e,value:0}),t.observe(e)})})})();
